        md5(normalise(upper(nullif(coalesce(nullif(trim(POLICY_REF),''),'') || '|NOMINEE|' || coalesce(nullif(trim(NOMINEENAME),''),''), '|NOMINEE|')))) as HUB_PARTY_BK__POLICY_REF_NOMINEE_NOMINEENAME,
        nullif(trim(CUST_ID),'') as HUB_PARTY_BK__CUST_ID,
        nullif(trim(POLICY_REF),'') as HUB_POLICY_BK__POLICY_REF,
        nullif('CUSTID:' || nullif(trim(CUST_ID),''), 'CUSTID:') as HUB_RISK_OBJECT_BK__CUSTID_CUST_ID,
        pay_status
    from {{ ref('stg_pmsby_data_web_service') }}
    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO, HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE, HUB_POLICY_BK__POLICY_REF, HUB_RISK_OBJECT_BK__CUSTID_CUST_ID order by HUB_DISTRIBUTION_CHANNEL_BK__USER_TRANS_KEY_NO, HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE, HUB_POLICY_BK__POLICY_REF, HUB_RISK_OBJECT_BK__CUSTID_CUST_ID) = 1
),

