    t23.HUB_POLICY_BK__PREV_POL_REF as T23__HUB_POLICY_BK__PREV_POL_REF,
    t23.HUB_POLICY_BK__REG_NO as T23__HUB_POLICY_BK__REG_NO,
    coalesce(t1.total_prem_on_base_cov_addon, t13.total_addon_premium, t17.add_on_prem) as ADD_ON_PREMIUM,
    coalesce(t11.total_base_premium, t1.total_prem_on_base_cov, t13.total_base_premium, t15.base_premium, t0.tot_sec_prem) as BASE_PREMIUM,
